package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.linear.*;

/** Proper continuous joint-normal data augmentation, not deterministic mean replacement. */
public final class GaussianImputation {
    private GaussianImputation(){}
    public record Options(int imputations,int burnIterations,long seed){public Options{if(imputations<2||imputations>100||burnIterations<20||burnIterations>2000)throw new IllegalArgumentException("Choose 2–100 imputations and 20–2,000 burn-in iterations per independent chain.");}public static Options defaults(){return new Options(20,200,42);}}
    public record Result(Options options,int suppliedRows,List<Integer> sourceRows,int missingCells,List<double[][]> completed,double[][][] meanTraces,double maximumSplitRhat,List<String> warnings){
        public Result{sourceRows=List.copyOf(sourceRows);completed=completed.stream().map(Matrices::copy).toList();meanTraces=Arrays.stream(meanTraces).map(Matrices::copy).toArray(double[][][]::new);warnings=List.copyOf(warnings);}
        @Override public List<double[][]> completed(){return completed.stream().map(Matrices::copy).toList();}@Override public double[][][] meanTraces(){return Arrays.stream(meanTraces).map(Matrices::copy).toArray(double[][][]::new);}
    }
    public static Result impute(double[][] input,Options options,java.util.function.IntConsumer progress){
        Objects.requireNonNull(options);if(input==null||input.length<5||input[0]==null)throw new IllegalArgumentException("Provide a nonempty rectangular continuous dataset.");int p=input[0].length;if(p<1||p>32)throw new IllegalArgumentException("Joint-normal imputation supports 1–32 selected variables.");List<Integer> retained=new ArrayList<>();int missing=0;
        for(int i=0;i<input.length;i++){var row=input[i];if(row==null||row.length!=p)throw new IllegalArgumentException("Imputation rows must have equal widths.");int present=0;for(double x:row){if(Double.isInfinite(x))throw new IllegalArgumentException("Infinity is not a missing marker.");if(Double.isFinite(x))present++;}if(present>0){retained.add(i+1);missing+=p-present;}}
        int n=retained.size();if(n<p+4||n>10000||(long)n*p*options.imputations()>2000000)throw new IllegalArgumentException("Imputation needs at least p+4 informative rows, at most 10,000 rows and two million retained imputation cells.");double[] center=new double[p],sums=new double[p];int[] counts=new int[p];double[][] original=new double[n][p];
        for(int i=0;i<n;i++){original[i]=input[retained.get(i)-1].clone();for(int j=0;j<p;j++)if(Double.isFinite(original[i][j])){counts[j]++;double delta=original[i][j]-center[j];center[j]+=delta/counts[j];sums[j]+=delta*(original[i][j]-center[j]);}}
        double[] scale=new double[p];for(int j=0;j<p;j++){if(counts[j]<3||!(sums[j]>0)||!Double.isFinite(sums[j]))throw new IllegalArgumentException("Each selected variable needs at least three observed values and positive variance.");scale[j]=Math.sqrt(sums[j]/counts[j]);}
        List<String> warnings=new ArrayList<>();if(input.length>n)warnings.add((input.length-n)+" fully unobserved rows were excluded; no artificial units were introduced into complete-data analyses.");warnings.add("Continuous joint multivariate-normal imputation under ignorable MAR/MCAR. The reference prior p(mu,Sigma) is proportional to |Sigma|^(-(p+1)/2); each completed-data posterior draw has Sigma~IW(n-1,scatter), mu|Sigma~N(mean,Sigma/n). This is not an ordinal, MNAR or generally nonlinear-compatible imputer.");warnings.add("Every imputation uses an independently seeded data-augmentation chain. Review burn-in/trace behavior and missingness assumptions; a numerical diagnostic cannot prove convergence or congeniality with an arbitrary scientific model.");
        List<double[][]> completed=new ArrayList<>();int tail=Math.min(60,options.burnIterations());double[][][] traces=new double[options.imputations()][missing==0?0:tail][p];
        if(missing==0){for(int m=0;m<options.imputations();m++){completed.add(Matrices.copy(original));if(progress!=null)progress.accept(m+1);}warnings.add("No selected cells are missing: completed datasets are identical and between-imputation variance should be zero.");return new Result(options,input.length,retained,0,completed,traces,Double.NaN,warnings);}
        for(int chain=0;chain<options.imputations();chain++){
            Random rng=new Random(options.seed()+0x9E3779B97F4A7C15L*(chain+1));double[][] z=new double[n][p];for(int i=0;i<n;i++)for(int j=0;j<p;j++)z[i][j]=Double.isFinite(original[i][j])?(original[i][j]-center[j])/scale[j]:rng.nextGaussian()*.1;
            for(int iteration=0;iteration<options.burnIterations();iteration++){
                Matrices.interrupted();double[] mean=new double[p];for(var row:z)for(int j=0;j<p;j++)mean[j]+=row[j]/n;double[][] scatter=new double[p][p];for(var row:z)for(int a=0;a<p;a++)for(int b=0;b<p;b++)scatter[a][b]+=(row[a]-mean[a])*(row[b]-mean[b]);RealMatrix sigma=inverseWishart(scatter,n-1,rng);RealMatrix lower=cholesky(sigma).getL();double[] normal=normals(p,rng);double[] mu=new double[p];for(int j=0;j<p;j++){mu[j]=mean[j];for(int k=0;k<p;k++)mu[j]+=lower.getEntry(j,k)*normal[k]/Math.sqrt(n);}
                Map<String,Conditional> cache=new HashMap<>();for(int row=0;row<n;row++){if((row&63)==0)Matrices.interrupted();final int index=row;int[] absent=java.util.stream.IntStream.range(0,p).filter(j->Double.isNaN(original[index][j])).toArray();if(absent.length==0)continue;Conditional condition=cache.computeIfAbsent(Arrays.toString(absent),key->conditional(sigma,absent));double[] residual=new double[condition.observed().length];for(int j=0;j<residual.length;j++)residual[j]=z[row][condition.observed()[j]]-mu[condition.observed()[j]];double[] conditionalMean=condition.regression().operate(residual),draw=condition.lower().operate(normals(absent.length,rng));for(int j=0;j<absent.length;j++)z[row][absent[j]]=mu[absent[j]]+conditionalMean[j]+draw[j];}
                if(iteration>=options.burnIterations()-tail)for(int j=0;j<p;j++)traces[chain][iteration-(options.burnIterations()-tail)][j]=center[j]+scale[j]*mu[j];
            }
            double[][] result=new double[n][p];for(int i=0;i<n;i++)for(int j=0;j<p;j++)result[i][j]=Double.isFinite(original[i][j])?original[i][j]:center[j]+scale[j]*z[i][j];completed.add(result);if(progress!=null)progress.accept(chain+1);
        }
        double rhat=maximumSplitRhat(traces);if(!Double.isFinite(rhat)||rhat>1.1)warnings.add("The mean-trace split R-hat screening exceeds 1.1 or is unavailable. Increase burn-in and investigate before interpreting pooled results. This screening is not rank-normalized Bayesian convergence certification.");return new Result(options,input.length,retained,missing,completed,traces,rhat,warnings);
    }
    record Conditional(int[] observed,RealMatrix regression,RealMatrix lower){}
    private static Conditional conditional(RealMatrix sigma,int[] absent){Set<Integer> missing=new HashSet<>();for(int j:absent)missing.add(j);int[] observed=java.util.stream.IntStream.range(0,sigma.getRowDimension()).filter(j->!missing.contains(j)).toArray();RealMatrix inverse=cholesky(sigma.getSubMatrix(observed,observed)).getSolver().getInverse(),regression=sigma.getSubMatrix(absent,observed).multiply(inverse),covariance=sigma.getSubMatrix(absent,absent).subtract(regression.multiply(sigma.getSubMatrix(observed,absent)));return new Conditional(observed,regression,cholesky(covariance.add(covariance.transpose()).scalarMultiply(.5)).getL());}
    static RealMatrix inverseWishart(double[][] scatter,int df,Random rng){int p=scatter.length;RealMatrix l=cholesky(new Array2DRowRealMatrix(scatter)).getL();double[][] a=new double[p][p];for(int i=0;i<p;i++){a[i][i]=Math.sqrt(2*gamma((df-i)*.5,rng));for(int j=0;j<i;j++)a[i][j]=rng.nextGaussian();}RealMatrix inverse=new LUDecomposition(new Array2DRowRealMatrix(a),1e-14).getSolver().getInverse();return l.multiply(inverse.transpose()).multiply(inverse).multiply(l.transpose());}
    private static CholeskyDecomposition cholesky(RealMatrix value){try{return new CholeskyDecomposition(value,1e-8,1e-12);}catch(NonPositiveDefiniteMatrixException|NonSymmetricMatrixException invalid){throw new IllegalArgumentException("Imputation covariance is singular or numerically inadmissible; no undisclosed ridge repair was applied.");}}
    private static double[] normals(int n,Random rng){double[] out=new double[n];for(int j=0;j<n;j++)out[j]=rng.nextGaussian();return out;}
    static double gamma(double shape,Random rng){if(!(shape>1))throw new IllegalArgumentException("Insufficient posterior covariance degrees of freedom.");double d=shape-1.0/3,c=1/Math.sqrt(9*d);while(true){Matrices.interrupted();double x=rng.nextGaussian(),v=1+c*x;if(v<=0)continue;v=v*v*v;double u=rng.nextDouble();if(u<1-.0331*x*x*x*x||Math.log(u)<.5*x*x+d*(1-v+Math.log(v)))return d*v;}}
    static double maximumSplitRhat(double[][][] traces){int chains=traces.length,half=traces[0].length/2,p=traces[0].length==0?0:traces[0][0].length;if(half<2)return Double.NaN;double maximum=1;for(int j=0;j<p;j++){double[] mean=new double[2*chains],variance=new double[2*chains];for(int c=0;c<chains;c++)for(int split=0;split<2;split++){int k=2*c+split;for(int i=0;i<half;i++)mean[k]+=traces[c][split*half+i][j]/half;for(int i=0;i<half;i++){double delta=traces[c][split*half+i][j]-mean[k];variance[k]+=delta*delta/(half-1);}}double average=Arrays.stream(mean).average().orElseThrow(),within=Arrays.stream(variance).average().orElseThrow(),between=0;for(double m:mean)between+=half*(m-average)*(m-average)/(mean.length-1);if(!(within>0))return Double.NaN;maximum=Math.max(maximum,Math.sqrt(((half-1.0)/half*within+between/half)/within));}return maximum;}
}
